export function MessageBubble({
  text = "{{text}}",
  sender = "{{sender}}",
  accent = "{{accent}}",
  timestamp = "{{timestamp}}",
  tail = {{tail}},
}) {
  const align = sender === "user" ? "flex-end" : "flex-start";
  const bubbleStyle = {
    user: { background: accent, borderBottomRightRadius: 4 },
    assistant: { background: "#24143010", borderBottomLeftRadius: 4 },
    system: { background: "transparent", border: "1.5px dashed #24143040", fontStyle: "italic" },
  }[sender] ?? {};
  const tailStyle = tail
    ? sender === "user"
      ? { position: "absolute", right: -6, bottom: 0, width: 12, height: 12, background: accent, clipPath: "polygon(0 0, 0% 100%, 100% 100%)" }
      : sender === "assistant"
        ? { position: "absolute", left: -6, bottom: 0, width: 12, height: 12, background: "#24143010", clipPath: "polygon(100% 0, 0 100%, 100% 100%)" }
        : null
    : null;
  return (
    <div style={{ maxWidth: 420, display: "flex", flexDirection: "column", alignItems: align, font: "15px/1.4 system-ui, sans-serif", marginBottom: 4 }}>
      <span style={{ fontSize: 11, fontWeight: 600, textTransform: "uppercase", letterSpacing: ".04em", color: "#24143080", marginBottom: 4 }}>{sender}</span>
      <div style={{ position: "relative", maxWidth: 320, padding: "10px 14px", borderRadius: 16, color: "#241430", ...bubbleStyle }}>
        <p style={{ margin: 0 }}>{text}</p>
        <span style={{ display: "block", marginTop: 4, fontSize: 11, color: "#24143080" }}>{timestamp}</span>
        {tailStyle && <span aria-hidden="true" style={tailStyle} />}
      </div>
    </div>
  );
}
